n  console.log(`warp:${content}`);\n  return content.replace(/\\n/g, '<br>');\n}\n\nfunction emojiHandle() {}\n\nconst fontSize = computed(() => {\n  if (sharedState.ST.isMobile) {\n    return '13px';\n  } else {\n    return '15px';\n  }\n});\n\nconst headSize = computed(() => {\n  if (sharedState.ST.isMobile) {\n    return '32px';\n  } else {\n    return '40px';\n  }\n});\n\nconst messageBottom = computed(() => {\n  if (sharedState.ST.isMobile) {\n    return '10px';\n  } else {\n    return '20px';\n  }\n});\n</script>\n\n<style>\n.QQ_chat_mymsg,\n.QQ_chat_charmsg {\n  margin-bottom: v-bind(messageBottom);\n}\n\n.QQ_chat_head {\n  width: v-bind(headSize);\n  height: v-bind(headSize);\n  border-radius: 50%;\n  background-size: cover;\n  min-width: v-bind(headSize);\n}\n\n.groupmsg {\n  margin-top: 6px;\n}\n\n.QQ_chat_msgdiv {\n  background-color: v-bind(bubbleColor);\n  span {\n    color: v-bind(textColor);\n  }\n  font-size: v-bind(fontSize);\n}\n</style>\n"],"sourceRoot":""}]);
